(function(){'use strict';
/* STAGING LOCALE BUILD (pl) — generated by scripts/build_locale_staging.py from assets/growth/tools.js.
 * Only string literals and display formatting differ. Formulas, weights, thresholds, clamping and toFixed() rounding are
 * unchanged; fx() formats the already-rounded value with Intl.NumberFormat. Parity: scripts/locale_tools_parity.js. */
const LOC="pl-PL";
const fx=(n,d)=>new Intl.NumberFormat(LOC,{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n.toFixed(d)));
const PLC=n=>(n===1?"{n} wybrany sygnał":(n>=2&&n<=4)?"{n} wybrane sygnały":"{n} wybranych sygnałów").replace('{n}',String(n));
const VCS_LINK="„{phrase}” w VC Says";

const $=id=>document.getElementById(id), num=id=>{const el=$(id);if(!el)return 0;let v=Number(el.value);if(!Number.isFinite(v))return 0;if(el.min!==''&&Number.isFinite(Number(el.min)))v=Math.max(Number(el.min),v);if(el.max!==''&&Number.isFinite(Number(el.max)))v=Math.min(Number(el.max),v);return v};
const money=(n)=>new Intl.NumberFormat(LOC,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number.isFinite(n)?n:0);
const pct=(n)=>fx(Number.isFinite(n)?n:0,1)+'\u00a0%';
function event(name,props={}){try{if(window.posthog&&typeof window.posthog.capture==='function')window.posthog.capture(name,props);if(typeof window.gtag==='function')window.gtag('event',name,props)}catch(e){}}
function bindCalculate(id,fn){const b=$(id);if(!b)return;b.addEventListener('click',()=>{fn();event('tfg_tool_completed',{tool_slug:document.body.dataset.tool||'unknown'})});}
function set(id,value){const el=$(id);if(el)el.textContent=String(value)}
function copyText(txt,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(txt).then(()=>{if(button)button.textContent="Skopiowano ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}).catch(()=>fallback())}else fallback();function fallback(){let ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');if(button)button.textContent="Skopiowano ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}catch(e){if(button)button.textContent="Tekst należy zaznaczyć i skopiować ręcznie"}ta.remove()}}
const signalItems=[
{key:'next',label:"Proponuje konkretne kolejne spotkanie lub termin",weight:4,group:'action'},
{key:'partner',label:"Umawia rozmowę z innym partnerem lub osobą decyzyjną",weight:4,group:'action'},
{key:'diligence',label:"Prosi o konkretne dokumenty do due diligence lub referencje klientów",weight:3,group:'action'},
{key:'champion',label:"Jasno wyjaśnia, jak przebiega wewnętrzny proces decyzyjny funduszu",weight:2,group:'action'},
{key:'question',label:"Zadaje konkretne, pogłębiające pytania o Państwa biznes",weight:1,group:'interest'},
{key:'polite',label:"Mówi „ciekawe, prosimy informować nas na bieżąco” bez kolejnego kroku",weight:-2,group:'caution'},
{key:'noresponse',label:"Uzgodniony termin odpowiedzi minął bez żadnej informacji",weight:-2,group:'caution'},
{key:'wrong',label:"Mówi, że etap, sektor, geografia lub kwota inwestycji nie pasują",weight:-4,group:'caution'},
];
function initSignals(){const wrap=$('signals-list');if(!wrap)return;signalItems.forEach(s=>{let lab=document.createElement('label');lab.className='formcheck';let ch=document.createElement('input');ch.type='checkbox';ch.name='signal';ch.value=s.key;lab.appendChild(ch);lab.append(document.createTextNode(s.label));wrap.appendChild(lab)});bindCalculate('signals-calculate',()=>{const chosen=[...document.querySelectorAll('input[name="signal"]:checked')].map(x=>signalItems.find(s=>s.key===x.value));const score=chosen.reduce((sum,x)=>sum+x.weight,0);const actions=chosen.filter(x=>x.group==='action').length;let status="Niewystarczający sygnał",desc="Na razie brakuje dowodów na konkretny proces. Warto zapytać o dopasowanie do profilu inwestora i o kolejny punkt decyzyjny.",next="Wysłać krótki, konkretny follow-up z prośbą o odpowiedni kolejny krok i kontynuować rozmowy z innymi inwestorami.";if(chosen.some(x=>x.key==='wrong')){status="Prawdopodobne niedopasowanie strukturalne";desc="Wyraźne niedopasowanie co do etapu, tezy inwestycyjnej, geografii lub kwoty inwestycji waży więcej niż przyjazny ton.";next="Podziękować, zapytać o lepiej dopasowaną osobę lub fundusz i przenieść ten kontakt poza aktywny lejek."}else if(score>=5&&actions>=2){status="Istotne sygnały procesu";desc="Kilka konkretnych kroków wskazuje na rzeczywisty proces oceny; nadal nie gwarantuje to inwestycji.";next="Potwierdzić na piśmie osoby odpowiedzialne, materiały i terminy. Równolegle prowadzić pozostałe rozmowy."}else if(score>=2&&actions>=1){status="Pierwsze oznaki zaangażowania";desc="Konkretne działanie mówi więcej niż komplementy, ale proces nie jest jeszcze rozstrzygający.";next="Zrealizować prośbę i zapytać, jaka będzie kolejna decyzja i kiedy zapadnie."}else if(score<0){status="Słaba lub słabnąca dynamika";desc="Uprzejme zainteresowanie bez działań albo niedotrzymane zobowiązania wymagają wyjaśnienia, a nie optymistycznej interpretacji.";next="Przesłać jedną merytoryczną aktualizację i poprosić o jasne „tak” lub „nie” w sprawie dalszych rozmów; nie wymyślać sztucznych terminów."}const rel=$('signal-related');if(rel){const has=k=>chosen.some(x=>x.key===k);const id=has('wrong')?'not-right-fit':has('noresponse')?'investor-ghosting':has('partner')?'partner-introduction':has('next')?'second-meeting':has('polite')?'keep-in-touch':null;rel.textContent='';if(id)rel.appendChild(vcSaysLink(id,"Powiązany poradnik do zwrotu: "));else{const a=document.createElement('a');a.href="/pl/vc-says";a.textContent="Przeglądaj VC Says: typowe zwroty inwestorów i sposoby odpowiedzi";rel.appendChild(a)}}set('signal-status',status);set('signal-desc',desc);set('signal-next',next);set('signal-count',PLC(chosen.length));$('signal-meter').style.width=Math.max(5,Math.min(100,(score+8)*5))+'%';});}
function initPipeline(){if(!$('pipeline-calculate'))return;const run=()=>{const leads=num('pipe-leads'), r1=num('pipe-r1')/100,r2=num('pipe-r2')/100,r3=num('pipe-r3')/100,r4=num('pipe-r4')/100;let first=leads*r1,second=first*r2,terms=second*r3,closed=terms*r4;set('pipe-meetings',fx(first,1));set('pipe-deep',fx(second,1));set('pipe-terms',fx(terms,2));set('pipe-closes',fx(closed,2));set('pipe-close-rate',pct(leads>0?closed/leads*100:0));let target=Math.max(.0000001,r1*r2*r3*r4);set('pipe-needed',Math.ceil(1/target).toLocaleString(LOC));set('pipe-note',terms<1?"Przy tych założeniach oczekiwana liczba term sheetów jest mniejsza niż jeden. Warto poprawić dopasowanie inwestorów, konwersję lub liczbę kontaktów; wyniki nie są gwarantowane.":"To model wartości oczekiwanej, a nie prognoza rzeczywistych zobowiązań. Przy małych liczbach wyniki mogą się znacznie różnić.");};bindCalculate('pipeline-calculate',run);run();}
function initRunway(){if(!$('runway-calculate'))return;const run=()=>{const cash=num('run-cash'),net=Math.max(0,num('run-expenses')-num('run-revenue')),months=num('run-months'),one=num('run-onetime'),buffer=num('run-buffer')/100,pre=num('run-pre');const core=Math.max(0,net*months+one-cash),raise=core*(1+buffer),post=pre+raise,dil=post>0?raise/post*100:0,existing=net>0?cash/net:Infinity;set('run-net',money(net));set('run-existing',Number.isFinite(existing)?fx(existing,1):"Brak burnu netto");set('run-raise',money(raise));set('run-dilution',pct(dil));set('run-post',money(post));set('run-pool',money(raise-core));set('run-note',pre<=0?"Aby obliczyć uproszczone rozwodnienie, należy podać dodatnią wycenę pre-money.":"Wyłącznie poglądowa runda z ustaloną wyceną: nie uwzględnia puli opcji, SAFE, pożyczek konwertowalnych, opłat ani zmian burnu. Warunki transakcji należy potwierdzić z doradcami.");};bindCalculate('runway-calculate',run);run();}
const templates={
 meeting:{subject:"Dziękuję za dzisiejszą rozmowę – [nazwa firmy]",intro:"Dziękuję za dzisiejszą rozmowę oraz za Państwa spostrzeżenia dotyczące tematu: [temat].",mid:"Zgodnie z ustaleniami prześlę [obiecany materiał]. Najważniejsza aktualizacja z naszej strony: [postęp].",ask:"Czy jako kolejny krok odpowiadałaby Państwu następująca propozycja: [konkretny kolejny krok]?"},
 tooearly:{subject:"Re: [nazwa firmy] – postępy względem kamienia milowego",intro:"Dziękuję za szczerą informację zwrotną, że w świetle Państwa obecnych kryteriów inwestycyjnych możemy być jeszcze na zbyt wczesnym etapie.",mid:"Od naszej ostatniej rozmowy osiągnęliśmy następujący postęp: [postęp]. Skupiamy się na kamieniu milowym, o którym była mowa: [kamień milowy].",ask:"Czy osiągnięcie tego kamienia milowego przybliżyłoby nas do Państwa progu inwestycyjnego, czy też istnieje inna luka, którą powinniśmy najpierw wypełnić?"},
 quiet:{subject:"Krótka aktualizacja: [nazwa firmy]",intro:"Wracam do naszej rozmowy dotyczącej tematu: [temat].",mid:"Krótka aktualizacja od naszej ostatniej rozmowy: [postęp].",ask:"Czy nadal są Państwo zainteresowani kontynuowaniem rozmowy, czy lepiej odezwać się ponownie po osiągnięciu kamienia milowego: [kamień milowy]? Każda odpowiedź będzie dla nas pomocna."},
 update:{subject:"[nazwa firmy] – aktualizacja: [postęp]",intro:"Jeszcze raz dziękuję za propozycję pozostania w kontakcie po naszej rozmowie dotyczącej tematu: [temat].",mid:"Najważniejsza zmiana od naszej rozmowy: [postęp]. Kolejny cel, nad którym pracujemy, to kamień milowy: [kamień milowy].",ask:"Czy chcieliby Państwo nadal otrzymywać nasze krótkie aktualizacje dla inwestorów, czy może jest konkretny wskaźnik, o którym chcieliby Państwo usłyszeć w pierwszej kolejności?"},
 notfit:{subject:"Re: [nazwa firmy] – dziękuję",intro:"Dziękuję za jasną odpowiedź w kwestii dopasowania – doceniam, że nie musimy zgadywać.",mid:"Jeśli znajdą Państwo chwilę: czy chodziło głównie o etap, sektor czy geografię? Pomoże nam to skupić się na lepiej dopasowanych inwestorach.",ask:"Jeśli przychodzi Państwu na myśl fundusz, który zwykle inwestuje w firmy takie jak nasza, każda wskazówka będzie dla nas bardzo cenna."},
 nolead:{subject:"[nazwa firmy] – struktura rundy",intro:"Dziękuję za jasną informację, że warunkiem jest dla Państwa wcześniejsze pozyskanie inwestora wiodącego.",mid:"Obecnie koncentrujemy się na pozyskaniu inwestora wiodącego. Najważniejsza aktualizacja: [postęp].",ask:"Jeśli pozyskamy inwestora wiodącego na warunkach w omawianym przedziale, jaką kwotę inwestycji byliby Państwo skłonni rozważyć i czy mają Państwo wymagania co do tego, kto powinien prowadzić rundę? Bardzo cenne byłyby także kontakty do funduszy, które prowadzą rundy na naszym etapie."},
 cold:{subject:"[nazwa firmy] – krótki follow-up",intro:"Nawiązuję do mojej wcześniejszej wiadomości dotyczącej firmy [nazwa firmy], która pomaga [klient] osiągać [wynik].",mid:"Jedna istotna nowość: [postęp].",ask:"Czy mieści się to w obecnym obszarze zainteresowań Państwa funduszu? W razie potrzeby chętnie prześlę zwięzłe podsumowanie."}
};
/* Shared VC Says signal IDs (data/vc_signals.expanded.json). tpl = Follow-up Builder scenario. */
const VC_SAYS={'too-early':{phrase:"To dla nas jeszcze za wczesny etap.",tpl:'tooearly'},'not-right-fit':{phrase:"To nie jest projekt dla naszego funduszu.",tpl:'notfit'},'keep-in-touch':{phrase:"Bądźmy w kontakcie.",tpl:'update'},'circle-back-next-quarter':{phrase:"Odezwijcie się w przyszłym kwartale.",tpl:'update'},'send-deck':{phrase:"Podeślijcie mi deck.",tpl:'meeting'},'second-meeting':{phrase:"Umówmy się na kolejne spotkanie.",tpl:'meeting'},'partner-introduction':{phrase:"Przedstawię was jednemu z naszych partnerów.",tpl:'meeting'},'need-more-traction':{phrase:"Chcielibyśmy zobaczyć większą trakcję.",tpl:'tooearly'},'no-lead-investor':{phrase:"Odezwijcie się, gdy będziecie mieć inwestora wiodącego.",tpl:'nolead'},'investor-ghosting':{phrase:"Brak odpowiedzi po dwóch przypomnieniach.",tpl:'quiet'}};
function signalFromQuery(){try{const id=new URLSearchParams(location.search).get('signal');return id&&Object.prototype.hasOwnProperty.call(VC_SAYS,id)?id:null}catch(e){return null}}
function vcSaysLink(id,prefix){const p=document.createElement('span');p.append(document.createTextNode(prefix));const a=document.createElement('a');a.href="/pl/vc-says/"+id;a.textContent=VCS_LINK.replace('{phrase}',VC_SAYS[id].phrase.replace(/[.?!]$/,''));p.appendChild(a);p.append(document.createTextNode('.'));return p}
function clean(str,alt){let x=(str||'').trim().replace(/[\r\n]+/g,' ').slice(0,450);return x||alt}
function initFollowup(){if(!$('followup-calculate'))return;const sig=signalFromQuery();if(sig){const sel=$('follow-type');if(sel&&[...sel.options].some(o=>o.value===VC_SAYS[sig].tpl))sel.value=VC_SAYS[sig].tpl;const note=$('follow-signal-note');if(note){note.textContent='';note.appendChild(vcSaysLink(sig,"Sytuacja wybrana na podstawie wpisu w VC Says: "));note.hidden=false}event('tfg_followup_signal_prefill',{signal_id:sig})}const run=()=>{const type=$('follow-type').value,t=templates[type],company=clean($('follow-company').value,'[nazwa firmy]'),person=clean($('follow-name').value,'[imię inwestora]'),topic=clean($('follow-topic').value,"nasza działalność"),progress=clean($('follow-progress').value,"[konkretny, weryfikowalny postęp]"),milestone=clean($('follow-milestone').value,"[uzgodniony kamień milowy]"),next=clean($('follow-next').value,"krótka rozmowa uzupełniająca");let subs={subject:t.subject,intro:t.intro,mid:t.mid,ask:t.ask};for(let k in subs){subs[k]=subs[k].replaceAll('[nazwa firmy]',company).replaceAll('[temat]',topic).replaceAll('[postęp]',progress).replaceAll('[kamień milowy]',milestone).replaceAll('[konkretny kolejny krok]',next)}const out=`Temat: ${subs.subject}\n\nDzień dobry, ${person},\n\n${subs.intro}\n\n${subs.mid}\n\n${subs.ask}\n\nZ pozdrowieniami\n[Twoje imię]`; $('follow-output').value=out;};bindCalculate('followup-calculate',run);$('follow-copy').addEventListener('click',function(){copyText($('follow-output').value,this)});run();}
function init(){initSignals();initPipeline();initRunway();initFollowup();document.querySelectorAll('a[href="/#join"],a[href="/#join"],a.button[href="/"],a[data-signup-cta]').forEach(a=>a.addEventListener('click',()=>event('tfg_signup_cta_clicked',{source_path:location.pathname,tool_slug:document.body.dataset.tool||undefined,article_slug:document.body.dataset.article||undefined})));
if(document.body.dataset.tool){event('tfg_tool_viewed',{tool_slug:document.body.dataset.tool,pathname:location.pathname});}
if(document.body.dataset.article){event('tfg_article_viewed',{article_slug:document.body.dataset.article,pathname:location.pathname});}let tracked=false;const main=document.querySelector('main');if(main)main.addEventListener('input',()=>{if(!tracked&&document.body.dataset.tool){event('tfg_tool_started',{tool_slug:document.body.dataset.tool});tracked=true}},{once:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
